// Patches the native iOS/Android projects generated by `flutter create` with
// everything Cotopole needs. Idempotent — safe to run repeatedly.
//
//   dart run tool/configure_platforms.dart
//
// iOS:     camera/photo usage strings, display name, URL schemes, export
//          compliance flag, and iOS 15.5 minimum (required by Google ML Kit).
// Android: app label and <queries> for tel/sms/mailto/https intents.

// ignore_for_file: avoid_print
import 'dart:io';

const iosMin = '15.5';

const plistEntries = <String, String>{
  'NSCameraUsageDescription':
      '<string>Cotopole uses the camera to photograph business cards and, with their consent, the person you met.</string>',
  'NSPhotoLibraryUsageDescription':
      '<string>Cotopole lets you choose a business card or client photo from your library.</string>',
  'LSApplicationQueriesSchemes':
      '<array>\n\t\t<string>tel</string>\n\t\t<string>sms</string>\n\t\t<string>mailto</string>\n\t\t<string>https</string>\n\t</array>',
  'ITSAppUsesNonExemptEncryption': '<false/>',
};

void main() {
  var ok = true;
  ok &= _ios();
  ok &= _android();
  print(ok ? '\n✔ Platforms configured.' : '\n✖ Some steps failed — see above.');
  if (!ok) exitCode = 1;
}

bool _ios() {
  final plist = File('ios/Runner/Info.plist');
  if (!plist.existsSync()) {
    print('✖ ios/Runner/Info.plist not found. Run: flutter create . --platforms ios,android');
    return false;
  }
  var s = plist.readAsStringSync();

  for (final e in plistEntries.entries) {
    if (s.contains('<key>${e.key}</key>')) {
      print('• Info.plist already has ${e.key}');
      continue;
    }
    final idx = s.lastIndexOf('</dict>');
    s = '${s.substring(0, idx)}\t<key>${e.key}</key>\n\t${e.value}\n${s.substring(idx)}';
    print('✔ Info.plist: added ${e.key}');
  }

  // Display name shown under the icon.
  s = s.replaceFirstMapped(
    RegExp(r'(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)'),
    (m) => '${m[1]}Cotopole${m[2]}',
  );
  plist.writeAsStringSync(s);

  // Deployment target: Podfile + Xcode project (+ legacy AppFrameworkInfo).
  final podfile = File('ios/Podfile');
  if (podfile.existsSync()) {
    var p = podfile.readAsStringSync();
    final re = RegExp(r"^#?\s*platform :ios, '[\d.]+'", multiLine: true);
    p = re.hasMatch(p) ? p.replaceFirst(re, "platform :ios, '$iosMin'") : "platform :ios, '$iosMin'\n$p";
    podfile.writeAsStringSync(p);
    print('✔ Podfile: platform :ios, $iosMin');
  } else {
    print('• No ios/Podfile yet — it is created on first `flutter build ios` / `pod install`. '
        'Re-run this script afterwards to set platform :ios, $iosMin.');
  }

  final pbx = File('ios/Runner.xcodeproj/project.pbxproj');
  if (pbx.existsSync()) {
    final t = pbx
        .readAsStringSync()
        .replaceAll(RegExp(r'IPHONEOS_DEPLOYMENT_TARGET = [\d.]+;'), 'IPHONEOS_DEPLOYMENT_TARGET = $iosMin;');
    pbx.writeAsStringSync(t);
    print('✔ Xcode project: IPHONEOS_DEPLOYMENT_TARGET = $iosMin');
  }

  final fw = File('ios/Flutter/AppFrameworkInfo.plist');
  if (fw.existsSync()) {
    final t = fw.readAsStringSync().replaceFirstMapped(
          RegExp(r'(<key>MinimumOSVersion</key>\s*<string>)[^<]*(</string>)'),
          (m) => '${m[1]}$iosMin${m[2]}',
        );
    fw.writeAsStringSync(t);
  }
  return true;
}

bool _android() {
  final manifest = File('android/app/src/main/AndroidManifest.xml');
  if (!manifest.existsSync()) {
    print('✖ AndroidManifest.xml not found. Run: flutter create . --platforms ios,android');
    return false;
  }
  var s = manifest.readAsStringSync();

  s = s.replaceFirst(RegExp(r'android:label="[^"]*"'), 'android:label="Cotopole"');

  const intents = {
    'android.intent.action.DIAL': 'tel',
    'android.intent.action.SENDTO': 'mailto',
    'android.intent.action.VIEW': 'https',
  };
  final missing = StringBuffer();
  intents.forEach((action, scheme) {
    if (!s.contains('android:scheme="$scheme"')) {
      missing.write('''
        <intent>
            <action android:name="$action" />
            <data android:scheme="$scheme" />
        </intent>
''');
    }
  });
  if (!s.contains('android:scheme="sms"')) {
    missing.write('''
        <intent>
            <action android:name="android.intent.action.SENDTO" />
            <data android:scheme="sms" />
        </intent>
''');
  }

  if (missing.isNotEmpty) {
    if (s.contains('<queries>')) {
      s = s.replaceFirst('<queries>', '<queries>\n$missing');
    } else {
      s = s.replaceFirst('</manifest>', '    <queries>\n$missing    </queries>\n</manifest>');
    }
    print('✔ AndroidManifest: added <queries> for tel/sms/mailto/https');
  } else {
    print('• AndroidManifest already has the needed <queries>');
  }
  manifest.writeAsStringSync(s);
  return true;
}
